import{c as s,Q as n,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000001902028081.DRz0Nzh9.png",l="/assets/SoftmaxGradFront%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.DbRtfeC2.png",g=JSON.parse('{"title":"SoftmaxGradFront","description":"","frontmatter":{},"headers":[{"level":1,"title":"SoftmaxGradFront","slug":"softmaxgradfront"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGradFront.md","filePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGradFront.md"}'),o={name:"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxGradFront.md"};function r(i,a,d,c,h,f){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="softmaxgradfront" tabindex="-1">SoftmaxGradFront <a class="header-anchor" href="#softmaxgradfront" aria-label="Permalink to &quot;SoftmaxGradFront&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将输入tensor[m0, m1, ...mt, n]（t大于等于0）的非尾轴长度相乘的结果看作m，则输入tensor的shape看作[m, n]。对输入tensor[m,n]按行做gradfront反向计算，计算公式如下：</p><p><img src="'+p+`" alt=""></p><p>当输入shape为ND格式时，内部的reduce过程按last轴进行；当输入shape为NZ格式时，内部的reduce过程按照last轴和first轴进行，reduce过程可以参考<a href="./SoftMax.html">SoftMax</a>中的图示说明。</p><p>为方便理解，通过Python脚本实现的方式，表达其计算公式如下，其中dx、y是源操作数（输入），d为目的操作数（输出）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def softmax_grad_front(dx, y, is_fp16=False):</span></span>
<span class="line"><span>    dx = dx.astype(np.float32)</span></span>
<span class="line"><span>    y = y.astype(np.float32)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    d = (dx * y).sum(axis=-1, keepdims=True)  ###[1024,1]</span></span>
<span class="line"><span>    if is_fp16:</span></span>
<span class="line"><span>        d = d.astype(np.float16)</span></span>
<span class="line"><span>    return d</span></span></code></pre></div><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以float类型，ND格式，shape为[m, k]的输入Tensor为例，描述SoftmaxGradFront高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> SoftmaxGradFront算法框图<br><img src="`+l+`" alt="" title="SoftmaxGradFront算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>mul步骤：对输入x和y所有数据相乘，计算结果会保存到一个临时空间temp中；</li><li>reducesum步骤：对temp中的数据([m, k])每一行数据求和得到[m, 1]，计算结果保存到临时空间中；</li><li>broadcast步骤：对[m, 1]做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]，并输出结果z。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isBasicBlock = false, bool isDataFormatNZ = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxGradFront(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; gradTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isBasicBlock = false, bool isDataFormatNZ = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxGradFront(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; gradTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./SoftmaxGrad-Tiling接口.html">SoftmaxGrad Tiling接口</a>中提供的GetSoftMaxGradMaxTmpSize/GetSoftMaxGradMinTmpSize接口获取所需最小和最大临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isBasicBlock</td><td>srcTensor和gradTensor的shape信息和Tiling切分策略满足基本块要求的情况下，可以使能该参数用于提升性能，默认不使能。是否满足基本块的要求，可以采用如下两种方式之一判断： srcTensor和dstTensor的shape信息[m,n]需要满足如下条件：尾轴长度n小于2048并且大于等于256/sizeof(T)（即half场景下n最小为128，float场景下n最小为64），同时n是64的倍数；非尾轴长度的乘积m为8的倍数。 在Tiling实现中，通过调用IsBasicBlockInSoftMax判断Tiling切分策略是否满足基本块的切分要求。 针对Atlas 200I/500 A2 推理产品，该参数为预留参数，暂未启用，为后续的功能扩展做保留，保持默认值即可。</td></tr><tr><td>isDataFormatNZ</td><td>当前输入输出的数据格式是否为NZ格式，默认数据格式为ND，即默认取值为false。 针对Atlas 200I/500 A2 推理产品，不支持配置为NZ格式。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度固定32Byte即一个datablock长度，并且该datablock中的所有数据为同一个值。比如half数据类型下，该datablock里的16个数均为相同的值，非last轴长度需要和srcTensor保持一致。</td></tr><tr><td>gradTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐，gradTensor的shape与srcTensor的shape一致。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐，srcTensor的shape与gradTensor的shape一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时空间。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 该操作数的数据类型固定uint8_t。 用于接口内部复杂计算时存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考SoftmaxGrad Tiling接口。</td></tr><tr><td>tiling</td><td>输入</td><td>softmaxgradfront计算所需tiling信息，Tiling信息的获取请参考SoftmaxGrad Tiling接口。</td></tr><tr><td>softmaxShapeInfo</td><td>输入</td><td>srcTensor的shape信息。SoftMaxShapeInfo类型，具体定义如下方代码所示，其中参数的含义为： srcM：非尾轴长度的乘积。srcK：尾轴长度，必须32Byte对齐oriSrcM：原始非尾轴长度的乘积。oriSrcK：原始尾轴长度。 需要注意，当输入输出的数据格式为NZ格式时，尾轴长度为reduce轴长度即图2中的W0<em>W1，非尾轴为H0</em>H1。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct SoftMaxShapeInfo {</span></span>
<span class="line"><span>  uint32_t srcM; </span></span>
<span class="line"><span>  uint32_t srcK; </span></span>
<span class="line"><span>  uint32_t oriSrcM;  </span></span>
<span class="line"><span>  uint32_t oriSrcK;  </span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</li><li>当参数softmaxShapeInfo中srcM != oriSrcM 或者 srcK != oriSrcK时，开发者需要对GM上的原始输入(oriSrcM, oriSrcK)在M或K方向补齐数据到(srcM, srcK)，补齐的数据会参与部分运算，在输入输出复用的场景下，API的计算结果会覆盖srcTensor中补齐的原始数据，在输入输出不复用的场景下，API的计算结果会覆盖dstTensor中对应srcTensor补齐位置的数据。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放SoftmaxGradFront计算结果的Tensor</span></span>
<span class="line"><span>// gradLocal：存放SoftmaxGradFront计算的输入Tensor</span></span>
<span class="line"><span>// srcLocal：存放SoftmaxGradFront计算的输入Tensor</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放SoftmaxGradFront计算过程中临时缓存的Tensor</span></span>
<span class="line"><span>// softmaxTiling：存放SoftmaxGradFront计算所需Tiling信息，可通过SoftMaxGradTilingFunc接口获取</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::SoftMaxShapeInfo softmaxInfo(</span></span>
<span class="line"><span>    /* 非尾轴长度的乘积          */ srcM, </span></span>
<span class="line"><span>    /* 尾轴长度，必须32Bytes对齐 */ srcK, </span></span>
<span class="line"><span>    /* 原始非尾轴长度的乘积      */ oriSrcM, </span></span>
<span class="line"><span>    /* 原始尾轴长度              */ oriSrcK</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间</span></span>
<span class="line"><span>AscendC::SoftmaxGradFront&lt;T&gt;(dstLocal, gradLocal, srcLocal, sharedTmpBuffer, softmaxTiling, softmaxInfo);</span></span>
<span class="line"><span>// 接口框架申请临时空间</span></span>
<span class="line"><span>AscendC::SoftmaxGradFront&lt;T&gt;(dstLocal, gradLocal, srcLocal, softmaxTiling, softmaxInfo);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(gradLocal)：</span></span>
<span class="line"><span>[[-100.     -80.     -60.     -50.     -30.     -20.     -15.     -10.   ]</span></span>
<span class="line"><span> [  -9.      -8.      -7.      -6.      -5.      -4.      -3.      -2.   ]</span></span>
<span class="line"><span> [  -1.5     -1.      -0.8     -0.6     -0.5     -0.45    -0.4     -0.35 ]</span></span>
<span class="line"><span> [  -0.3     -0.25    -0.2     -0.15    -0.1     -0.05    -0.01    -0.001]</span></span>
<span class="line"><span> [   0.       0.001    0.01     0.05     0.1      0.15     0.2      0.25 ]</span></span>
<span class="line"><span> [   0.3      0.35     0.4      0.45     0.5      0.6      0.8      1.   ]</span></span>
<span class="line"><span> [   1.5      2.       3.       4.       5.       6.       7.       8.   ]</span></span>
<span class="line"><span> [   9.      10.      15.      20.      30.      50.      60.      80.   ]]</span></span>
<span class="line"><span>输入数据(srcLocal)：</span></span>
<span class="line"><span>[[2. 2. 2. 2. 2. 2. 2. 2.]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [2. 2. 2. 2. 2. 2. 2. 2.]]</span></span>
<span class="line"><span>输出数据(dstLocal)：</span></span>
<span class="line"><span>[[-730.   ]</span></span>
<span class="line"><span> [ -88.   ]</span></span>
<span class="line"><span> [ -11.2  ]</span></span>
<span class="line"><span> [  -2.122]</span></span>
<span class="line"><span> [   1.522]</span></span>
<span class="line"><span> [   8.8  ]</span></span>
<span class="line"><span> [  73.   ]</span></span>
<span class="line"><span> [ 548.   ]]</span></span></code></pre></div>`,33)])])}const u=s(o,[["render",r]]);export{g as __pageData,u as default};
